<?php /** @var array<string,mixed> $s */ /** @var bool $canConvert */ $u = '/scope-requests/' . $s['public_id']; $open = in_array($s['status'], ['submitted', 'assessing'], true); ?>
<div class="page-head"><div><p class="eyebrow"><a href="/scope-requests">Scope requests</a></p><h1><?= e($s['reference']) ?></h1><p class="muted"><a href="/projects/<?= e($s['project_public_id']) ?>"><?= e($s['project_code']) ?> · <?= e($s['project_title']) ?></a> · from <?= e($s['requester_name']) ?> · <?= e(ucfirst((string) $s['status'])) ?></p></div></div>
<div class="panel"><h2>What the client asked for</h2><p class="prewrap"><?= e($s['description']) ?></p><?php if ($s['wanted_by']) : ?><p class="muted">Wanted by <?= e(local_date($s['wanted_by'])) ?></p><?php endif; ?></div>
<?php if ($s['change_public_id']) : ?><div class="panel"><p>Proposal: <a href="/changes/<?= e($s['change_public_id']) ?>"><?= e($s['change_reference']) ?></a> (<?= e(str_replace('_', ' ', (string) $s['change_status'])) ?>)</p></div><?php endif; ?>
<?php if ($open) : ?><div class="panel"><h2>Assess</h2><p class="muted">Estimate the extra cost and how many days it adds. This is saved privately; the client sees nothing until you create the proposal.</p>
    <form method="post" action="<?= e($u) ?>" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="assess">
        <div class="field"><label for="a">Extra cost (₹)</label><input id="a" name="amount" required inputmode="decimal" value="<?= e(old('amount', $s['est_amount_minor'] !== null ? number_format((int) $s['est_amount_minor'] / 100, 2, '.', '') : '')) ?>"></div>
        <div class="field"><label for="d">Extra days</label><input id="d" name="days" inputmode="numeric" value="<?= e(old('days', (string) ($s['est_days'] ?? ''))) ?>"></div>
        <div class="field"><label for="n">Note</label><input id="n" name="note" maxlength="1000" value="<?= e(old('note', (string) $s['assessment_note'])) ?>"></div>
        <div class="form-actions"><button class="btn btn-ghost" type="submit">Save assessment</button></div></form>
    <?php if ($s['status'] === 'assessing' && $canConvert) : ?><form method="post" action="<?= e($u) ?>" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="convert"><h3>Create the proposal for the client</h3>
        <div class="field"><label for="sc">Scope text <span class="muted">(empty = the client's own words)</span></label><textarea id="sc" name="scope" rows="3"></textarea></div><div class="field"><label for="rs">Why it is extra work <span class="muted">(shown to the client)</span></label><textarea id="rs" name="reason" rows="3"></textarea></div>
        <div class="form-actions"><button class="btn btn-primary" type="submit">Create change proposal (draft)</button></div></form><?php endif; ?>
    <form method="post" action="<?= e($u) ?>" class="form-grid" data-confirm="Decline this request?"><?= csrf_field() ?><input type="hidden" name="action" value="decline"><h3>Decline</h3><div class="field"><label for="r">Reason shown to the client</label><input id="r" name="reason" required maxlength="1000"></div><div class="field"><label for="p">Your password</label><input id="p" name="confirm_password" type="password" required autocomplete="current-password"></div><div class="form-actions"><button class="btn btn-danger btn-sm" type="submit">Decline</button></div></form></div><?php endif; ?>
